int main() {
    long long x, n = 0, lo = 0, hi = 0;
    while (std::cin >> x) {
        if (n == 0) lo = hi = x;
        lo = std::min(lo, x);
        hi = std::max(hi, x);
        n++;
    }
    std::cout << n << " " << lo << " " << hi << "\n";
}

